CREATE TABLE drafts(id TEXT PRIMARY KEY,title TEXT NOT NULL,text TEXT NOT NULL,images TEXT NOT NULL,stage TEXT NOT NULL,error TEXT NOT NULL,notes TEXT NOT NULL,created INTEGER NOT NULL)
CREATE TABLE batches(draft_id TEXT NOT NULL REFERENCES drafts(id) ON DELETE CASCADE,number INTEGER NOT NULL,json TEXT NOT NULL,PRIMARY KEY(draft_id,number))
CREATE TABLE usage(id INTEGER PRIMARY KEY AUTOINCREMENT,draft_id TEXT NOT NULL,input_tokens INTEGER NOT NULL,output_tokens INTEGER NOT NULL,cache_hit INTEGER NOT NULL,cache_miss INTEGER NOT NULL)
CREATE TABLE dictionary(lemma TEXT PRIMARY KEY,meanings TEXT NOT NULL)
CREATE TABLE context_cache(key TEXT PRIMARY KEY,json TEXT NOT NULL)
CREATE TABLE ocr_cache(key TEXT PRIMARY KEY,json TEXT NOT NULL)
CREATE TABLE articles(id TEXT PRIMARY KEY REFERENCES drafts(id),title TEXT NOT NULL,text TEXT NOT NULL,hash TEXT NOT NULL UNIQUE,created INTEGER NOT NULL)
CREATE TABLE paragraphs(article_id TEXT NOT NULL REFERENCES articles(id) ON DELETE CASCADE,number INTEGER NOT NULL,start INTEGER NOT NULL,text TEXT NOT NULL,translation TEXT NOT NULL,PRIMARY KEY(article_id,number))
CREATE TABLE occurrences(article_id TEXT NOT NULL REFERENCES articles(id) ON DELETE CASCADE,token_id INTEGER NOT NULL,surface TEXT NOT NULL,start INTEGER NOT NULL,end INTEGER NOT NULL,paragraph INTEGER NOT NULL,lemma TEXT NOT NULL,pos TEXT NOT NULL,meaning TEXT NOT NULL,common TEXT NOT NULL,PRIMARY KEY(article_id,token_id))
CREATE INDEX word_index ON occurrences(lemma)
CREATE TABLE phrases(article_id TEXT NOT NULL REFERENCES articles(id) ON DELETE CASCADE,ids TEXT NOT NULL,text TEXT NOT NULL,meaning TEXT NOT NULL,PRIMARY KEY(article_id,ids))
CREATE TABLE clicks(lemma TEXT PRIMARY KEY,count INTEGER NOT NULL)
CREATE TABLE cards(id TEXT PRIMARY KEY,lemma TEXT NOT NULL,pos TEXT NOT NULL,meaning TEXT NOT NULL,common TEXT NOT NULL,article_id TEXT NOT NULL REFERENCES articles(id),token_id INTEGER NOT NULL,context TEXT NOT NULL,repetitions INTEGER NOT NULL,lapses INTEGER NOT NULL,due INTEGER NOT NULL,rating INTEGER NOT NULL)
CREATE INDEX due_index ON cards(due)
CREATE TABLE analysis_fragments(draft_id TEXT NOT NULL REFERENCES drafts(id) ON DELETE CASCADE,number INTEGER NOT NULL,json TEXT NOT NULL,PRIMARY KEY(draft_id,number))
CREATE TABLE selection_cache(key TEXT PRIMARY KEY,translation TEXT NOT NULL)
ALTER TABLE cards ADD COLUMN reviews INTEGER NOT NULL DEFAULT 0
